<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../api';const data=ref<any>({orders:[],paymentChannels:[]});onMounted(async()=>data.value=(await api.get('/admin/commerce')).data);</script><template><section class="page"><h1 class="page-title">交易中心</h1><div class="cards"><div class="card"><span>今日订单</span><div class="metric">{{data.orders.length}}</div></div><div class="card"><span>支付通道</span><div class="metric">{{data.paymentChannels.length}}</div></div></div><el-table :data="data.orders" style="margin-top:18px"><el-table-column prop="orderNo" label="订单号"/><el-table-column prop="user" label="用户"/><el-table-column prop="amount" label="金额"/><el-table-column prop="status" label="状态"/></el-table></section></template>
